# calculator.py

def add(a, b):
    return a + b

def sub(a, b):
    return a - b

def mul(a, b):
    return a * b

def div(a, b):
    return a / b

functions = {"+": add, "-": sub, "*": mul, "/": div}

def main():
    print("Calculator (type q to quit)")
    while True:
        text = input("First number (or q): ").strip()
        if text.lower() == "q":
            break
        try:
            a = float(text)
            op = input("Operator (+, -, *, /): ").strip()
            b = float(input("Second number: ").strip())
        except ValueError:
            print("Please enter a number.")
            continue
        func = functions.get(op)
        if func is None:
            print("Unknown operator.")
            continue
        try:
            print(func(a, b))
        except ZeroDivisionError:
            print("Cannot divide by zero.")

if __name__ == "__main__":
    main()
